/**
 * 현장 질문에서 모은 '정해 둔 답' — 결제·영업·계정·보안·개인정보처럼 공개 문서로 끝까지 풀 수 없거나,
 * 단정하면 안 되는 질문에 바로 답한다. 페르소나 상호 평가 루프(6회차~)에서 심사관이 지적한 질문을 모았다.
 *
 * 지키는 것
 * - 사실은 공개 문서(lib/docs.ts 등)에 있는 것만 쓴다. 없으면 "공개 안내에 없다"고 밝히고 담당자에게 넘긴다.
 * - 가격·할인·환불·복구·일정은 약속하지 않는다. 아이디·전화번호·카드 번호를 채팅창에 적으라고 하지 않는다.
 * - 패턴은 좁게 쓴다. 넓은 패턴은 다른 질문의 답을 가로챈다.
 *
 * 증상·사용법처럼 문서 단계로 답할 질문은 symptom-topics-field.ts에 둔다.
 */

export interface FieldQuickAnswer {
  id: string
  /** 질문(소문자) 기준 판별. */
  match: (text: string) => boolean
  answer: string[]
  /** 있으면 상담 연결 버튼과 함께 답한다(support: 실시간 상담, demo: 도입 상담). */
  handoff?: "support" | "demo"
  category: string
  suggestedQuestions: string[]
  /** 영어로 물었을 때 첫 줄에 붙일 요약. */
  en?: string
  /** true면 끝에 영업용 되묻기(규모·도입 시기)를 붙여도 된다. 기본은 붙이지 않는다(정해 둔 답이 필요한 것을 이미 묻는다). */
  salesFollowUp?: boolean
}

const has = (pattern: RegExp) => (text: string) => pattern.test(text)
const all =
  (...patterns: RegExp[]) =>
  (text: string) =>
    patterns.every((pattern) => pattern.test(text))

